import pandas as pd
import numpy as np

# Load the data
df = pd.read_csv('chunks_csv/getisord/getisord_2023_ghg.csv')
adjacency_df = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Create a dictionary to store the neighbors of each borough
neighbors = {}
for index, row in adjacency_df.iterrows():
    if row['borough'] not in neighbors:
        neighbors[row['borough']] = []
    neighbors[row['borough']].append(row['neighbor'])

# Create a dictionary to store the combined GHG values for each borough and its neighbors
combined_values = {}
for borough in df['borough'].unique():
    if borough in neighbors:
        combined_values[borough] = df.loc[df['borough'] == borough, 'GHG_value'].values[0] + sum(df.loc[df['borough'] == neighbor, 'GHG_value'].values for neighbor in neighbors[borough])
    else:
        combined_values[borough] = df.loc[df['borough'] == borough, 'GHG_value'].values[0]

# Calculate the z-score for each borough
z_scores = {}
for borough in combined_values:
    mean = df['GHG_value'].mean()
    std_dev = df['GHG_value'].std()
    z_scores[borough] = (combined_values[borough] - mean) / std_dev

# Identify hot and cold spots
hot_spots = []
cold_spots = []
for borough, z_score in z_scores.items():
    if abs(z_score) > 1.96:
        if z_score > 0:
            hot_spots.append((borough, z_score))
        else:
            cold_spots.append((borough, z_score))

# Print the final answer
print(f"FINAL ANSWER: {', '.join([f'{borough} (HOT, z-score = {z_score:.4f})' if (borough, z_score) in hot_spots else f'{borough} (COLD, z-score = {z_score:.4f})' if (borough, z_score) in cold_spots else '' for borough, z_score in z_scores.items()])}")
```

This code first loads the data and creates a dictionary to store the neighbors of each borough. It then creates another dictionary to store the combined GHG values for each borough and its neighbors. The z-score for each borough is calculated, and hot and cold spots are identified. Finally, the final answer is printed in the required format.
